def calculate_a(N):
    a = {1: 1, 2: 1}
    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        an_minus_1 = a[n - 1]

        # Check if indices are valid (they should be since a_k >= 1)
        idx1 = an_minus_1
        idx2 = n - an_minus_1

        if idx1 not in a or idx2 not in a:
            # This should not happen for small N if the sequence is well-defined
            print(f"Error: Index out of bounds at n={n}")
            return None

        a[n] = a[idx1] + a[idx2]
    return a

N_max = 30
a_values = calculate_a(N_max)

if a_values:
