    print("---|---")
    for n in range(1, N_max + 1):
        print(f"{n:<2} | {a_values[n]}")

def solve_sequence(N):
    # a[i] stores a_{i+1}
    # We need storage for indices 1 to N, so size N+1.
    # Using 1-based indexing for clarity: a[n] = a_n
    a = [0] * (N + 1)

    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # We need a_{n-1} first. Let k = a_{n-1}
        k = a[n-1]

        # Check for potential index overflow/out of bounds
        if k > N or n - k <= 0:
            # This should ideally not happen if N is large enough and the sequence is well-behaved.
            # If it does, we stop or handle the error.
            a[n] = "ERROR"
            continue

        term1 = a[k]
        term2 = a[n - k]

        a[n] = term1 + term2

    return a

N_target = 4096
try:
    A = solve_sequence(N_target)

    print(f"--- Computed terms up to N={N_target} ---")

    # Check powers of 2: a_{2^k}
    print("\nChecking a_{2^k}:")
    for k in range(1, 13): # Check up to k=12, which is 4096
        n_power = 2**k
        if n_power <= N_target:
            val = A[n_power]
            expected = 2**(k-1) if k >= 1 else 0 # For k=1, 2^0=1. For k=2, 2^1=2.
            print(f"k={k}, n={n_power}: a_{n_power} = {val}. Expected pattern: {expected}")
        else:
            print(f"k={k}, n={n_power}: N_target too small.")

except Exception as e:
